def max_sum(arr):
    n = len(arr)
    if n == 0:
        return 0

    # Step 1: Compute the increasing subsequence sum (lis_sum)
    lis_sum = [0] * n
    for i in range(n):
        lis_sum[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i]:
                lis_sum[i] = max(lis_sum[i], lis_sum[j] + arr[i])

    # Step 2: Compute the decreasing subsequence sum (lds_sum)
    lds_sum = [0] * n
    for i in range(n - 1, -1, -1):
        lds_sum[i] = arr[i]
        for j in range(i + 1, n):
            if arr[j] < arr[i]:
                lds_sum[i] = max(lds_sum[i], lds_sum[j] + arr[i])

    # Step 3: Compute the maximum bitonic subsequence sum
    max_bitonic_sum = 0
    for i in range(n):
        max_bitonic_sum = max(max_bitonic_sum, lis_sum[i] + lds_sum[i] - arr[i])

    return max_bitonic_sum

# Example usage and test case
assert max_sum([1, 15, 51, 45, 33, 100, 12, 18, 9]) == 194
```

